/** @type {import("next").NextConfig} */
const nextConfig = {
  // Next 16 writes an AGENTS.md into the project on every dev start. The repo's
  // conventions live in CLAUDE.md and the docs, and a file regenerated by a build tool
  // would churn in every diff.
  agentRules: false,

  reactStrictMode: true,
  poweredByHeader: false,
  async headers() {
    // Security headers for the console itself. The API sets its own.
    return [
      {
        source: "/(.*)",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "Referrer-Policy", value: "no-referrer" },
          { key: "Permissions-Policy", value: "geolocation=(), camera=(), microphone=()" },
        ],
      },
    ];
  },
};

export default nextConfig;
